const content=document.querySelector('#content');
const modes=[{id:'speed',title:'60초 연산',icon:'× ÷',tag:'스피드 챌린지',desc:'60초 동안, 얼마나 많은 문제를 풀 수 있을까요?',detail:'사칙연산 · 제한 시간 60초'},{id:'blank',title:'빈칸의 비밀',icon:'□ +',tag:'생각하는 연습',desc:'비어 있는 숫자를 찾아 식을 완성해 보세요.',detail:'빈칸 추론 · 총 10문제'},{id:'compare',title:'어느 쪽이 클까?',icon:'≷',tag:'감각 깨우기',desc:'두 식을 비교하며 숫자 감각을 깨워 보세요.',detail:'크기 비교 · 총 10문제'}];
let difficulty='easy',state=null,timer=null,nextTimer=null;
let records=[];try{records=JSON.parse(localStorage.getItem('math-space-records')||'[]');if(!Array.isArray(records))records=[];records=records.filter(r=>r&&['speed','blank','compare'].includes(r.mode)&&['easy','normal','hard'].includes(r.level)&&['correct','total','accuracy'].every(k=>Number.isFinite(r[k])&&r[k]>=0)&&typeof r.date==='string'&&Number.isFinite(Date.parse(r.date))).slice(0,50)}catch{}
const levels={easy:'가볍게',normal:'적당히',hard:'도전하기'};
function stop(){clearInterval(timer);clearTimeout(nextTimer);timer=null;nextTimer=null;state=null}
function navigate(page){stop();document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='home')home();if(page==='records')showRecords();if(page==='guide')guide()}
function home(){content.innerHTML=`<section class="hero"><div class="eyebrow">A LITTLE MATH, A LITTLE EVERY DAY</div><h1>생각을 깨우는,<br>작은 <em>수학</em> 한 판.</h1><p>복잡한 준비 없이, 가볍게 시작해 보세요.<br>숫자와 친해지는 시간은 하루 몇 분이면 충분해요.</p></section><section class="settings"><div class="settings-label"><span>⚙</span><div>오늘은 어떤 속도로?<small>나에게 맞는 난이도를 골라 주세요</small></div></div><div class="chips">${Object.entries(levels).map(([k,v])=>`<button class="chip ${k===difficulty?'active':''}" data-level="${k}" aria-pressed="${k===difficulty}">${v}</button>`).join('')}</div></section><section><div class="section-heading"><h2>오늘의 놀이터</h2><small>마음이 가는 게임부터 시작하세요</small></div><div class="cards">${modes.map(m=>`<button class="game-card" data-mode="${m.id}"><div class="card-top"><span class="math-icon">${m.icon}</span><span class="tag">${m.tag}</span></div><h3>${m.title}</h3><p>${m.desc}</p><div class="card-bottom"><span>${m.detail}</span><span>시작하기 ↗</span></div></button>`).join('')}<div class="daily"><small>A MOMENT TO THINK</small><div class="quote">1% × 매일 = ∞</div><p>빠른 정답보다, 어제보다 조금 더 생각하는 나.</p></div></div></section><p class="bottom-note">시간이 없어도 괜찮아요. 한 판이면 충분하니까요.</p>`;content.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.level;home()});content.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(b.dataset.mode))}
const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
function expression(){let max={easy:10,normal:25,hard:60}[difficulty],a=rand(1,max),b=rand(1,max);let ops=difficulty==='easy'?['+','−']:['+','−','×','÷'];let op=ops[rand(0,ops.length-1)];if(op==='−'&&a<b)[a,b]=[b,a];if(op==='×'){a=rand(2,difficulty==='hard'?19:9);b=rand(2,9)}if(op==='÷'){b=rand(2,9);a=b*rand(2,difficulty==='hard'?19:9)}let value=op==='+'?a+b:op==='−'?a-b:op==='×'?a*b:a/b;return{a,b,op,value,text:`${a} ${op} ${b}`}}
function question(){let e=expression();if(state.mode==='compare'){let f=expression();if(Math.random()<.22)f={text:`${e.value-rand(1,5)} + `,value:e.value};if(f.text.endsWith('+ '))f.text+=e.value-Number(f.text.split(' ')[0]);return{text:`${e.text}　?　${f.text}`,answer:e.value>f.value?'>':e.value<f.value?'<':'=',options:['>','=','<']}}let blank=Math.random()<.5;let answer=state.mode==='blank'?(blank?e.a:e.b):e.value;let text=state.mode==='blank'?`${blank?'□':e.a} ${e.op} ${blank?e.b:'□'} = ${e.value}`:`${e.text} = ?`;let options=new Set([answer]);while(options.size<4)options.add(Math.max(0,answer+rand(-10,10)));return{text,answer,options:[...options].sort(()=>Math.random()-.5)}}
function start(mode){stop();state={mode,correct:0,total:0,streak:0,bestStreak:0,remaining:60,locked:false,started:Date.now()};content.innerHTML=`<section class="game-wrap"><div class="game-head"><button class="ghost" id="back">← 놀이터</button><span>${modes.find(m=>m.id===mode).title} · ${levels[difficulty]}</span></div><div class="stats"><div class="stat">${mode==='speed'?'남은 시간':'진행'}<strong id="time"></strong></div><div class="stat">맞힌 문제<strong id="score">0</strong></div><div class="stat">연속 정답<strong id="streak">0</strong></div></div><div class="progress"><span id="progress"></span></div><div class="question-box"><span class="eyebrow" id="q-label"></span><h1 id="question"></h1><div class="answers" id="answers"></div><div class="feedback" id="feedback" role="status" aria-live="polite"></div></div><p class="help">선택지를 클릭하거나 키보드 숫자 1–${mode==='compare'?3:4}을 눌러 답해 보세요.</p></section>`;document.querySelector('#back').onclick=()=>navigate('home');renderQuestion();if(mode==='speed')timer=setInterval(()=>{if(!state)return;state.remaining--;updateStats();if(state.remaining<=0)finish()},1000)}
function updateStats(){if(!state)return;document.querySelector('#time').textContent=state.mode==='speed'?`${state.remaining}초`:`${Math.min(state.total+1,10)} / 10`;document.querySelector('#score').textContent=state.correct;document.querySelector('#streak').textContent=state.streak;document.querySelector('#progress').style.width=`${state.mode==='speed'?state.remaining/60*100:state.total/10*100}%`}
function renderQuestion(){state.locked=false;state.q=question();updateStats();document.querySelector('#q-label').textContent=state.mode==='blank'?'빈칸에 들어갈 숫자는?':state.mode==='compare'?'알맞은 비교 기호를 골라 주세요':'차분하게, 한 문제씩';document.querySelector('#question').textContent=state.q.text;document.querySelector('#feedback').textContent='';const answers=document.querySelector('#answers');answers.style.gridTemplateColumns=state.mode==='compare'?'repeat(3,1fr)':'';answers.innerHTML=state.q.options.map((v,i)=>`<button class="answer" data-index="${i}" aria-label="${i+1}번: ${v}">${v}<small style="display:block;font-size:10px;margin-top:5px;opacity:.5">${i+1}</small></button>`).join('');answers.querySelectorAll('button').forEach(b=>b.onclick=()=>answer(Number(b.dataset.index)))}
function answer(index){if(!state||state.locked)return;state.locked=true;const correct=state.q.options[index]===state.q.answer;state.total++;if(correct){state.correct++;state.streak++;state.bestStreak=Math.max(state.streak,state.bestStreak)}else state.streak=0;document.querySelectorAll('.answer').forEach((b,i)=>{b.disabled=true;if(state.q.options[i]===state.q.answer)b.classList.add('correct');else if(i===index)b.classList.add('wrong')});document.querySelector('#feedback').textContent=correct?'정답이에요. 잘 풀었어요!':`괜찮아요. 정답은 ${state.q.answer}입니다.`;updateStats();nextTimer=setTimeout(()=>{if(state.mode!=='speed'&&state.total>=10)finish();else renderQuestion()},correct?650:1200)}
function finish(){if(!state)return;clearInterval(timer);clearTimeout(nextTimer);const s={...state},accuracy=s.total?Math.round(s.correct/s.total*100):0;records.unshift({mode:s.mode,level:difficulty,correct:s.correct,total:s.total,accuracy,date:new Date().toISOString()});records=records.slice(0,50);let saved=true;try{localStorage.setItem('math-space-records',JSON.stringify(records))}catch{saved=false}state=null;content.innerHTML=`<section class="game-wrap result"><div class="eyebrow">A LITTLE BETTER THAN YESTERDAY</div><h1>좋은 한 판이었어요.</h1><p>${modes.find(m=>m.id===s.mode).title} · ${levels[difficulty]}</p><div class="big">${s.correct}<span style="font-size:22px"> / ${s.total}</span></div><p>정확도 ${accuracy}% · 최고 연속 정답 ${s.bestStreak}개</p><p>${saved?'오늘의 작은 성취를 기록에 남겼어요.':'브라우저 저장이 제한되어 이번 기록은 창을 닫으면 사라져요.'}</p><div class="result-actions"><button class="primary" id="again">한 번 더 풀기 ↗</button><button class="ghost" id="home">놀이터로 돌아가기</button></div></section>`;document.querySelector('#again').onclick=()=>start(s.mode);document.querySelector('#home').onclick=()=>navigate('home')}
function showRecords(){content.innerHTML=`<h1 class="page-title">나의 작은 발자국</h1><p>한 판씩 쌓인 생각의 기록이에요. 최근 50판까지 보관해요.</p><div style="margin-top:32px">${records.length?records.map(r=>`<div class="record"><div>${modes.find(m=>m.id===r.mode)?.title||'수학 게임'} <small>· ${levels[r.level]||''}<br>${new Date(r.date).toLocaleString('ko-KR')}</small></div><div>${r.correct} / ${r.total}<br><small>정확도 ${r.accuracy}%</small></div></div>`).join(''):'<div class="empty">아직 기록이 없어요.<p>놀이터에서 첫 번째 한 판을 시작해 보세요.</p><button class="primary" id="first-game">놀이터로 가기 ↗</button></div>'}</div>`;const first=document.querySelector('#first-game');if(first)first.onclick=()=>navigate('home')}
function guide(){content.innerHTML=`<h1 class="page-title">가볍게 시작하는 방법</h1><p>잘하는 것보다, 즐겁게 생각하는 것이 먼저예요.</p><div class="guide"><h2>01. 오늘의 난이도를 골라요</h2><p>가볍게: 10 이하 덧셈과 뺄셈<br>적당히: 25 이하 덧셈·뺄셈과 구구단·나눗셈<br>도전하기: 60 이하 덧셈·뺄셈과 두 자릿수 곱셈·나눗셈</p><h2>02. 마음이 가는 게임을 시작해요</h2><p>60초 연산은 제한 시간 안에 최대한 많은 문제를 풀어요.<br>빈칸의 비밀은 빠진 숫자를, 어느 쪽이 클까는 두 식 사이의 기호를 찾아요.<br>빈칸과 비교 게임은 시간 제한 없이 10문제를 풀어요.</p><h2>03. 나만의 속도로 쌓아 가요</h2><p>정답을 고르면 바로 결과를 확인할 수 있어요. 키보드 숫자 1–4로도 선택할 수 있어요.<br>완료한 게임은 이 브라우저에 저장돼요. 브라우저 데이터를 지우면 기록도 사라져요.<br>게임 도중 놀이터로 돌아가면 진행 중인 판은 저장되지 않아요.</p></div>`}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('home')};document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.altKey||e.metaKey)return;const i=Number(e.key)-1;if(state&&!state.locked&&i>=0&&i<state.q.options.length){e.preventDefault();answer(i)}});home();
